import type { Restructure } from '@prompttoppt/validation'
import { DESIGNS, brandTheme, composeSlide } from '@prompttoppt/theme'
import type { Presentation, SlideContent, Theme } from '@prompttoppt/validation'
import type { Family } from './understand.ts'

/**
 * The scenario catalogue (docs/AI_EDIT_HONESTY_AND_SCENARIOS.md section 6) as DATA. Each scenario is what a person says, what a PERFECT understanding of it is (the model is not part of
 * these tests: they check our code), the state of the deck, the person's plan and flags, and the outcome that must come out. The suite that runs them (apps/editor/src/editor/assist-scenarios.test.ts)
 * goes through the real pipeline, the real editor commands, the verifier and the message composer.
 *
 * A capability is offered by the assistant only if at least one `success` scenario covers it (registry.ts isReady): delete the scenarios and the capability disappears from "what can you do".
 */
export type ScenarioClass = 'success' | 'partial' | 'already' | 'locked' | 'missing' | 'failed' | 'unsupported' | 'plan' | 'template' | 'flag' | 'owner' | 'multi' | 'undo' | 'discovery'

export interface Scenario {
  id: string
  /** the capability covered (or the kind of answer) */
  family: Family | 'unsupported' | 'help'
  cls: ScenarioClass
  say: string
  /** the perfect understanding */
  intent: { kind?: 'edit' | 'help' | 'review'; help?: 'all' | 'slide' | 'plan'; review?: 'all' | 'text' | 'design' | 'story'; tasks?: { family: Family; targets?: unknown[]; values?: Record<string, unknown> }[]; unsupported?: string[] }
  /** the deck before (the standard deck: s0 title + a picture "pic", s1 body, s2 process, s3 body, s4 body, s5 closing) */
  setup?: (d: Presentation) => void
  /** after the answer is made and before it is applied: something changes in between (a slide deleted, a picture removed) */
  between?: (d: Presentation) => void
  /** the slide on screen (1-based) */
  slide?: number
  ctx?: { logo?: { ok: true; primary: string | null; accent: string | null; aspect: number } | { ok: false; say: string }; morph?: boolean; premiumTemplates?: boolean; advancedEditor?: boolean; brandKit?: boolean; isOwner?: boolean; flags?: Record<string, boolean>; hasSources?: boolean; /** the deck's comment threads */ threads?: { id: string; slideId: string; status: 'open' | 'resolved'; comments: { authorName: string; body: string }[] }[]; /** the previous saved version: the deck with only its first N slides */ previousSlides?: number; /** the saved brand kits */ themes?: { id: string; name: string; kitName: string; designName: string; mode: 'light' | 'dark'; theme: Theme }[]; kits?: { id: string; name: string; primary: string | null; accent: string | null; headingFont: string | null; bodyFont: string | null; isDefault: boolean }[]; /** the export formats of the plan (default: all) */ exportFormats?: string[]; /** pictures are not stored with the deck (a crop cannot read them) */ noStoredPictures?: boolean; uploads?: { id: string; url: string; name: string }[]; brand?: { name: string | null; primary: string | null; accent: string | null; headingFont: string | null; bodyFont: string | null; logo: { url: string; aspect: number } | null } | null; /** what reading the named website gives (the network is not part of these tests) */ site?: { ok: true; brand: { host: string; name: string | null; primary: string | null; accent: string | null; accentDerived: boolean; heading: { family: string; original: string; exact: boolean } | null; body: { family: string; original: string; exact: boolean } | null; logo: { url: string; aspect: number } | null; confidence: 'high' | 'low' } } | { ok: false; say: string } }
  /** the plan the person confirmed (the option they chose in the last answer) */
  confirm?: Restructure
  /** part of the request is blocked (a locked slide, a template slide): the FIRST answer must ask "do the rest?" and change nothing; `expect` is then checked on the answer to "Yes, do the rest" */
  proceed?: true
  /** what the model answers when asked to PROPOSE (numbers only); the same answer for every try */
  proposal?: unknown
  /** element ids selected in the editor */
  selected?: string[]
  /** what the person wrote earlier in this conversation (a "yes" confirms what they asked before) */
  earlier?: string[]
  /** what a cut-out produces (the route's job: measured transparency), default 'transparent' */
  cutout?: 'transparent' | 'opaque'
  /** run first, and the assistant's own change is remembered (for undo) */
  prior?: { say: string; tasks: { family: Family; targets?: unknown[]; values?: Record<string, unknown> }[] }
  expect: { outcome: 'done' | 'partial' | 'nothing' | 'already' | 'answer' | 'info' | 'ask' | 'select' | 'ui' | 'kit'; applied?: RegExp[]; notes?: RegExp[]; text?: RegExp[]; notText?: RegExp[]; /** the model must not be asked to write anything */ noWriting?: boolean }
}

/** slide `i` rebuilt as a slide with far too much text (about 108 words), made by the layout engine like any other slide */
const heavy = (i: number) => (d: Presentation) => {
  const bullets = Array.from({ length: 6 }, (_, k) => `point ${k + 1} ` + 'word '.repeat(16).trim())
  const f = composeSlide({ layout: 'title-body', title: 'Heavy', bullets, speakerNotes: '', sources: [] } as SlideContent, d.theme, d.aspectRatio, () => `hv${i}-${Math.random().toString(36).slice(2, 8)}`)
  d.slides[i] = { ...d.slides[i]!, ...f } as never
}
const hardToRead = (i: number) => (d: Presentation) => { const s = d.slides[i]!; s.background = { type: 'color', value: '#101010' }; for (const e of s.elements) if (e.type === 'text') (e as { color: string }).color = '#202020' }
const both = (a: (d: Presentation) => void, b: (d: Presentation) => void) => (d: Presentation) => { a(d); b(d) }
const ACME = [{ id: 'k1', name: 'Acme', primary: '#1E3A8A', accent: '#EAB308', headingFont: 'Playfair Display', bodyFont: 'Inter', isDefault: true }]
const THEME_DESIGN = DESIGNS.find((d) => !d.premium && d.look.mode === 'light')!
const ACME_NIGHT: Theme = brandTheme(THEME_DESIGN, 'dark', { primary: '#1E3A8A', accent: '#EAB308', headingFont: 'Playfair Display', bodyFont: 'Inter', name: 'Acme' }, 'Acme night', 'brand-theme-t1')
const lock = (...ix: number[]) => (d: Presentation) => { for (const i of ix) d.slides[i]!.locked = true }
/** slides 2 and 4 are section dividers: the sections are [1], [2-3] (section 1) and [4-6] (section 2) */
const sections = (d: Presentation) => { for (const i of [1, 3]) d.slides[i]!.layoutId = 'section-divider' }
const gradientOn = (i: number) => (d: Presentation) => { const s = d.slides[i]!; s.background = { type: 'gradient', value: '#111111', gradient: { from: '#111111', to: '#EEEEEE', angle: 60 } }; s.ownLook = true }
const T = (family: Family, targets: unknown[] = [], values: Record<string, unknown> = {}) => ({ family, targets, values })
const slide = (n: number) => ({ by: 'number', n })

/** a table (header Plan / Price / Seats, three unsorted rows) on slide 2 */
/** slide 2 with animations: the body fades in, then the title flies in and pulses */
const withFx = (d: Presentation) => { const els = d.slides[1]!.elements; const t = els.find((e) => e.type === 'text' && e.role === 'title')!; const b = els.find((e) => e.type === 'text' && e.role === 'body')!; const fx = (id: string, elementId: string, category: 'entrance' | 'emphasis' | 'exit', type: string) => ({ id, elementId, category, type, start: 'click', duration: 600, delay: 0, easing: 'ease-out', repeat: 1, reverse: false }); d.slides[1]!.effects = [fx('fx1', b.id, 'entrance', 'fade-in'), fx('fx2', t.id, 'entrance', 'fly-in'), fx('fx3', t.id, 'emphasis', 'pulse')] as never }
const withTable = (d: Presentation) => { d.slides[1]!.elements.push({ id: 'tbl', type: 'table', x: 200, y: 500, width: 1200, height: 360, rotation: 0, locked: false, zIndex: 3, opacity: 1, header: ['Plan', 'Price', 'Seats'], rows: [['Basic', '$10', '5'], ['Pro', '$30', '20'], ['Team', '$25', '10']] } as never) }
/** a bar chart (A, B, C) on slide 2, with `series` series and the given values for the first */
const withChart = (d: Presentation, series = 1, values = [3, 9, 5]) => { d.slides[1]!.elements.push({ id: 'cht', type: 'chart', x: 200, y: 500, width: 900, height: 450, rotation: 0, locked: false, zIndex: 3, opacity: 1, chartType: 'bar', labels: ['A', 'B', 'C'], series: Array.from({ length: series }, (_, i) => ({ name: `S${i + 1}`, values: i === 0 ? values : [1, 2, 3] })) } as never) }

