/** families covered by at least one success (or, for undo, undo) scenario: what the registry may offer */
export const SCENARIO_FAMILIES: ReadonlySet<Family> = new Set(SCENARIOS.filter((s) => (s.cls === 'success' || s.cls === 'undo') && s.family !== 'unsupported' && s.family !== 'help').map((s) => s.family as Family))
